{
  "name": "ape-project",
  "version": "1.0.0",
  "description": "APE PROJECT — a 3D pixel-art survival horror laboratory escape",
  "type": "module",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
    "build": "vite build",
    "preview": "vite preview --host 0.0.0.0 --port 3002"
  },
  "dependencies": {
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^7.2.2"
  }
}

import { defineConfig } from 'vite';

export default defineConfig({
  base: './',
  server: {
    host: '0.0.0.0',
    port: 3002,
    strictPort: true,
  },
  build: {
    target: 'es2020',
    assetsInlineLimit: 0,
  },
});

@font-face {
  font-family: 'Silkscreen';
  src: url('/fonts/Silkscreen-Regular.ttf') format('truetype');
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Silkscreen';
  src: url('/fonts/Silkscreen-Bold.ttf') format('truetype');
  font-weight: 700;
  font-display: swap;
}
@font-face {
  font-family: 'Share Tech Mono';
  src: url('/fonts/ShareTechMono-Regular.ttf') format('truetype');
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('/fonts/Rajdhani-Regular.ttf') format('truetype');
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('/fonts/Rajdhani-Medium.ttf') format('truetype');
  font-weight: 500;
  font-display: swap;
}

:root {
  --ink: #050a07;
  --ink-2: #07120c;
  --moss: #8fab3d;
  --moss-bright: #c9e76c;
  --moss-deep: #324a22;
  --acid: #d8f77e;
  --bone: #e2e5c9;
  --steel: #8a9b90;
  --steel-dark: #26352d;
  --cyan: #76f5d0;
  --amber: #e9b95f;
  --red: #e15946;
  --blood: #7e1f18;
  --ui-border: rgba(184, 215, 155, 0.24);
  --ui-soft: rgba(214, 235, 188, 0.5);
  --panel: rgba(4, 12, 8, 0.72);
  --sans: 'Rajdhani', 'Trebuchet MS', sans-serif;
  --mono: 'Share Tech Mono', 'Courier New', monospace;
  --pixel: 'Silkscreen', 'Courier New', monospace;
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #020604;
  color: var(--bone);
  font-family: var(--sans);
  -webkit-font-smoothing: none;
  font-smooth: never;
  overscroll-behavior: none;
}

body {
  touch-action: none;
  user-select: none;
}

button,
kbd {
  font: inherit;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  isolation: isolate;
}

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  outline: none;
  background: #07120b;
}

/* --------------------------------------------------------------------- */
/* Film treatment                                                         */
/* --------------------------------------------------------------------- */

.scene-grade,
.scene-grain,
.scene-scanlines,
.threat-vignette,
.damage-flash {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.scene-grade {
  z-index: 2;
  background:
    radial-gradient(ellipse at 50% 42%, transparent 28%, rgba(1, 6, 3, 0.16) 63%, rgba(1, 5, 3, 0.72) 100%),
    linear-gradient(180deg, rgba(57, 82, 45, 0.09), transparent 18%, transparent 72%, rgba(4, 10, 5, 0.3));
  mix-blend-mode: multiply;
}

.scene-grain {
  z-index: 3;
  opacity: 0.09;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.95' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E");
  animation: grainShift 0.24s steps(2) infinite;
  mix-blend-mode: soft-light;
}

.scene-scanlines {
  z-index: 4;
  opacity: 0.12;
  background: repeating-linear-gradient(0deg, transparent 0, transparent 2px, rgba(0, 0, 0, 0.42) 3px);
  background-size: 100% 3px;
}

@keyframes grainShift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-2%, 1%); }
  50% { transform: translate(1%, -2%); }
  75% { transform: translate(2%, 2%); }
  100% { transform: translate(-1%, -1%); }
}

.threat-vignette {
  z-index: 5;
  opacity: 0;
  transition: opacity 0.6s ease;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(44, 7, 4, 0.52) 78%, rgba(59, 4, 2, 0.9) 100%);
  mix-blend-mode: multiply;
}

.threat-vignette.active {
  opacity: 1;
  animation: threatPulse 1.4s ease-in-out infinite;
}

@keyframes threatPulse {
  0%, 100% { filter: brightness(0.85); }
  45% { filter: brightness(1.35); }
}

.damage-flash {
  z-index: 30;
  opacity: 0;
  background: radial-gradient(ellipse at center, rgba(128, 8, 5, 0.12), rgba(112, 4, 1, 0.74));
  transition: opacity 0.08s linear;
}

.damage-flash.active {
  opacity: 1;
}

/* --------------------------------------------------------------------- */
/* Boot / loading                                                         */
/* --------------------------------------------------------------------- */

.loading {
  position: absolute;
  inset: 0;
  z-index: 90;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background:
    radial-gradient(circle at 50% 45%, rgba(24, 46, 27, 0.54), transparent 34%),
    #030805;
  transition: opacity 0.7s ease, visibility 0.7s;
}

.loading.done {
  opacity: 0;
  visibility: hidden;
}

.loading-mark {
  position: relative;
  width: 74px;
  height: 74px;
  display: grid;
  place-items: center;
  color: var(--moss-bright);
  font-family: var(--pixel);
  font-size: 25px;
}

.loading-ring {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(190, 228, 120, 0.22);
  transform: rotate(45deg);
  animation: ringSpin 4s linear infinite;
}

.loading-ring::before,
.loading-ring::after {
  content: '';
  position: absolute;
  background: var(--moss);
}

.loading-ring::before { width: 8px; height: 2px; left: -4px; top: 50%; }
.loading-ring::after { width: 2px; height: 8px; right: 50%; top: -4px; }

@keyframes ringSpin { to { transform: rotate(405deg); } }

.loading-kicker,
.loading-status {
  margin: 0;
  font-family: var(--mono);
  letter-spacing: 0.26em;
  font-size: 10px;
  color: var(--moss);
}

.loading-bar {
  width: min(300px, 64vw);
  height: 2px;
  background: rgba(173, 210, 135, 0.14);
  overflow: hidden;
}

.loading-bar i {
  display: block;
  width: 0;
  height: 100%;
  background: var(--moss-bright);
  box-shadow: 0 0 12px var(--moss);
  transition: width 0.25s;
}

.loading-status {
  color: rgba(203, 223, 179, 0.46);
  letter-spacing: 0.2em;
  min-height: 12px;
}

/* --------------------------------------------------------------------- */
/* Title screen                                                           */
/* --------------------------------------------------------------------- */

.start-screen {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: grid;
  grid-template-rows: auto 1fr auto auto auto;
  padding: clamp(20px, 3.5vw, 56px) clamp(20px, 5vw, 80px) clamp(18px, 2.8vw, 40px);
  background:
    linear-gradient(90deg, rgba(2, 7, 4, 0.86) 0%, rgba(3, 8, 5, 0.55) 31%, transparent 66%),
    linear-gradient(180deg, rgba(1, 4, 2, 0.62) 0%, transparent 24%, transparent 75%, rgba(1, 4, 2, 0.72));
  transition: opacity 0.9s ease, visibility 0.9s;
}

.start-screen::before {
  content: '';
  position: absolute;
  left: clamp(20px, 5vw, 80px);
  top: 14%;
  bottom: 14%;
  width: 1px;
  background: linear-gradient(180deg, transparent, rgba(190, 222, 150, 0.22) 16%, rgba(190, 222, 150, 0.22) 84%, transparent);
  opacity: 0.5;
}

.start-screen.out {
  opacity: 0;
  visibility: hidden;
}

.start-noise {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.05;
  background: repeating-linear-gradient(90deg, transparent 0 1px, rgba(191, 230, 150, 0.5) 2px 3px);
  mix-blend-mode: overlay;
}

.start-topline {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-left: 18px;
  font-family: var(--mono);
  font-size: clamp(8px, 0.8vw, 11px);
  letter-spacing: 0.18em;
  color: rgba(205, 226, 175, 0.58);
  text-transform: uppercase;
}

.signal {
  display: flex;
  align-items: center;
  gap: 8px;
}

.signal i {
  width: 5px;
  height: 5px;
  background: var(--red);
  box-shadow: 0 0 8px var(--red);
  animation: blink 1.8s steps(1) infinite;
}

@keyframes blink { 0%, 58% { opacity: 1; } 59%, 100% { opacity: 0.2; } }

.title-lockup {
  align-self: center;
  position: relative;
  padding-left: 18px;
  margin-top: -1.5vh;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--mono);
  font-size: clamp(8px, 0.85vw, 12px);
  letter-spacing: 0.26em;
  color: var(--moss);
  text-transform: uppercase;
}

.eyebrow .dash {
  display: block;
  width: 24px;
  height: 1px;
  background: var(--moss);
}

.game-title {
  position: relative;
  margin: 12px 0 8px;
  width: min-content;
  font-family: var(--pixel);
  font-weight: 700;
  font-size: clamp(58px, 10.6vw, 168px);
  line-height: 0.72;
  letter-spacing: -0.055em;
  text-transform: uppercase;
  color: #dbe7bd;
  text-shadow:
    4px 0 0 rgba(42, 65, 32, 0.85),
    0 4px 0 rgba(42, 65, 32, 0.85),
    8px 8px 0 rgba(3, 7, 4, 0.75),
    0 0 42px rgba(137, 172, 68, 0.07);
  filter: saturate(0.9);
}

.title-ape,
.title-project {
  display: block;
  position: relative;
  z-index: 2;
}

.title-ape {
  color: #c8dd9b;
  transform: translateX(-2px);
}

.title-project {
  color: transparent;
  -webkit-text-stroke: clamp(1.5px, 0.18vw, 3px) rgba(217, 233, 186, 0.9);
  text-stroke: 1px rgba(217, 233, 186, 0.9);
  transform: translateX(calc(1.2vw + 4px));
}

.title-project::after {
  content: 'PROJECT';
  position: absolute;
  left: 0;
  top: 2px;
  color: var(--moss);
  -webkit-text-stroke: 0;
  opacity: 0.2;
  clip-path: inset(47% 0 16% 0);
  transform: translateX(5px);
  z-index: -1;
}

.title-shadow {
  position: absolute;
  z-index: 1;
  left: 8px;
  top: 9px;
  color: rgba(0, 0, 0, 0.4);
  pointer-events: none;
}

.title-tagline {
  margin: clamp(18px, 2.4vh, 30px) 0 0;
  font-family: var(--mono);
  font-size: clamp(11px, 1.16vw, 17px);
  line-height: 1.55;
  letter-spacing: 0.16em;
  color: rgba(228, 234, 207, 0.56);
}

.title-tagline em {
  color: var(--acid);
  font-style: normal;
  text-shadow: 0 0 16px rgba(184, 226, 93, 0.22);
}

.start-brief {
  position: relative;
  width: min(420px, 74vw);
  margin-left: 18px;
  margin-bottom: clamp(18px, 3vh, 36px);
  padding-top: 12px;
  border-top: 1px solid var(--ui-border);
}

.brief-index {
  display: flex;
  justify-content: space-between;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.19em;
  color: var(--moss);
}

.brief-index b {
  color: rgba(230, 238, 214, 0.8);
  font-weight: 400;
}

.start-brief p {
  margin: 9px 0 13px;
  font-size: clamp(12px, 1.04vw, 15px);
  line-height: 1.45;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: rgba(225, 232, 207, 0.68);
}

.brief-rule {
  display: flex;
  align-items: center;
  gap: 10px;
  color: rgba(214, 162, 91, 0.82);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.16em;
  white-space: nowrap;
}

.brief-rule span {
  flex: 1;
  height: 1px;
  background: rgba(214, 162, 91, 0.22);
}

.brief-rule i { font-style: normal; }

.start-btn {
  position: relative;
  justify-self: start;
  margin-left: 18px;
  margin-bottom: clamp(16px, 2.2vh, 30px);
  width: min(360px, 78vw);
  display: flex;
  align-items: stretch;
  gap: 0;
  padding: 0;
  background: rgba(13, 25, 14, 0.74);
  border: 1px solid rgba(197, 223, 147, 0.42);
  color: var(--bone);
  cursor: pointer;
  text-align: left;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.6), inset 0 0 40px rgba(130, 170, 65, 0.05);
  transition: background 0.2s, border-color 0.2s, transform 0.2s;
}

.start-btn:hover {
  background: rgba(35, 55, 24, 0.84);
  border-color: var(--moss-bright);
  transform: translateX(3px);
}

.start-btn:hover .start-btn-icon {
  background: var(--moss-bright);
  color: var(--ink);
}

.start-btn-icon {
  width: 56px;
  display: grid;
  place-items: center;
  background: rgba(159, 194, 85, 0.16);
  border-right: 1px solid rgba(197, 223, 147, 0.28);
  color: var(--moss-bright);
  font-size: 15px;
  transition: 0.2s;
}

.start-btn-copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 13px 18px 12px;
}

.start-btn-copy b {
  font-family: var(--pixel);
  font-size: clamp(10px, 1vw, 12px);
  letter-spacing: 0.1em;
  font-weight: 400;
}

.start-btn-copy small {
  font-family: var(--mono);
  color: rgba(210, 227, 185, 0.42);
  font-size: 8px;
  letter-spacing: 0.12em;
}

.start-btn-corner {
  position: absolute;
  width: 5px;
  height: 5px;
  border: 1px solid var(--moss);
  pointer-events: none;
}
.start-btn-corner.tl { left: -1px; top: -1px; border-right: 0; border-bottom: 0; }
.start-btn-corner.tr { right: -1px; top: -1px; border-left: 0; border-bottom: 0; }
.start-btn-corner.bl { left: -1px; bottom: -1px; border-right: 0; border-top: 0; }
.start-btn-corner.br { right: -1px; bottom: -1px; border-left: 0; border-top: 0; }

.start-controls {
  justify-self: start;
  display: flex;
  flex-wrap: wrap;
  gap: clamp(12px, 2.2vw, 30px);
  margin-left: 18px;
  margin-bottom: 18px;
}

.start-controls > div {
  display: flex;
  align-items: center;
  gap: 7px;
}

.start-controls kbd {
  min-width: 28px;
  padding: 4px 6px;
  border: 1px solid rgba(194, 220, 158, 0.3);
  border-bottom-color: rgba(194, 220, 158, 0.55);
  background: rgba(20, 33, 18, 0.55);
  color: rgba(221, 236, 198, 0.8);
  font-family: var(--mono);
  font-size: 8px;
  text-align: center;
  letter-spacing: 0.05em;
}

.start-controls span {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.14em;
  color: rgba(211, 227, 190, 0.38);
}

.start-footer {
  display: flex;
  justify-content: space-between;
  padding-top: 13px;
  border-top: 1px solid rgba(185, 215, 150, 0.12);
  font-family: var(--mono);
  font-size: clamp(7px, 0.65vw, 9px);
  letter-spacing: 0.18em;
  color: rgba(202, 220, 178, 0.32);
}

/* --------------------------------------------------------------------- */
/* HUD general                                                            */
/* --------------------------------------------------------------------- */

.hud {
  position: absolute;
  inset: 0;
  z-index: 20;
  pointer-events: none;
  font-family: var(--mono);
}

.hud.is-hidden {
  display: none;
}

.hud-top {
  position: absolute;
  top: max(18px, env(safe-area-inset-top));
  left: max(20px, env(safe-area-inset-left));
  right: max(20px, env(safe-area-inset-right));
  display: grid;
  grid-template-columns: minmax(190px, 1fr) minmax(280px, 1.6fr) minmax(190px, 1fr);
  align-items: start;
  gap: 22px;
}

.brand-panel {
  display: flex;
  align-items: center;
  gap: 11px;
  max-width: 300px;
  filter: drop-shadow(0 2px 8px rgba(0, 0, 0, 0.8));
}

.brand-mark {
  width: 39px;
  height: 39px;
  display: grid;
  place-items: center;
  flex: none;
  border: 1px solid rgba(188, 219, 143, 0.5);
  background:
    linear-gradient(135deg, rgba(155, 192, 84, 0.18), transparent 50%),
    rgba(4, 13, 8, 0.62);
  clip-path: polygon(0 0, 78% 0, 100% 22%, 100% 100%, 22% 100%, 0 78%);
  font-family: var(--pixel);
  font-size: 12px;
  color: var(--moss-bright);
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.brand-copy b {
  font-family: var(--pixel);
  font-size: 10px;
  letter-spacing: 0.13em;
  font-weight: 400;
  color: rgba(229, 238, 209, 0.9);
}

.brand-copy span {
  display: flex;
  align-items: center;
  gap: 6px;
  color: rgba(201, 221, 177, 0.42);
  font-size: 8px;
  letter-spacing: 0.13em;
}

.live-dot {
  width: 4px;
  height: 4px;
  background: var(--moss-bright);
  box-shadow: 0 0 6px var(--moss);
  animation: blink 1.4s steps(1) infinite;
}

/* compass */

.compass-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.compass-readout {
  display: flex;
  gap: 14px;
  align-items: center;
  font-size: 9px;
  letter-spacing: 0.16em;
  color: rgba(216, 234, 190, 0.48);
}

.compass-readout span:first-child {
  color: var(--acid);
  text-shadow: 0 0 10px rgba(180, 228, 93, 0.3);
}

.compass {
  position: relative;
  width: min(520px, 44vw);
  height: 26px;
  overflow: hidden;
  border-top: 1px solid rgba(185, 216, 145, 0.26);
  border-bottom: 1px solid rgba(185, 216, 145, 0.12);
  background: linear-gradient(180deg, rgba(2, 9, 5, 0.25), rgba(2, 9, 5, 0.55));
  mask-image: linear-gradient(90deg, transparent, black 12%, black 88%, transparent);
}

.compass-strip {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  white-space: nowrap;
  will-change: transform;
}

.compass-strip i {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  flex: none;
  font-style: normal;
  font-size: 8px;
  color: rgba(208, 228, 183, 0.34);
  position: relative;
}

.compass-strip i::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 1px;
  height: 4px;
  background: rgba(208, 228, 183, 0.26);
  transform: translate(-50%, 9px);
}

.compass-strip i.cardinal {
  color: rgba(220, 238, 196, 0.8);
  font-size: 10px;
}

.compass-notch {
  position: absolute;
  left: 50%;
  top: 0;
  height: 100%;
  width: 1px;
  background: var(--moss-bright);
  box-shadow: 0 0 8px rgba(194, 238, 110, 0.8);
}

.compass-notch::before {
  content: '';
  position: absolute;
  left: -3px;
  top: 0;
  border-left: 3px solid transparent;
  border-right: 3px solid transparent;
  border-top: 4px solid var(--moss-bright);
}

.marker-row {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 12px;
  font-size: 8px;
  letter-spacing: 0.09em;
  color: rgba(203, 226, 172, 0.5);
}

.marker-row span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.marker-row i {
  display: inline-block;
  width: 4px;
  height: 4px;
  background: var(--cyan);
}

.marker-row i.warn { background: var(--red); }

/* objective panel */

.objective-panel {
  justify-self: end;
  width: min(300px, 100%);
  padding: 11px 13px 12px;
  border-top: 1px solid rgba(195, 222, 153, 0.34);
  border-right: 1px solid rgba(195, 222, 153, 0.1);
  background:
    linear-gradient(110deg, rgba(16, 28, 15, 0.72), rgba(3, 10, 6, 0.52)),
    repeating-linear-gradient(0deg, transparent 0 7px, rgba(162, 198, 114, 0.025) 8px);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
  filter: drop-shadow(0 4px 12px rgba(0, 0, 0, 0.36));
}

.panel-cap {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--moss);
  font-size: 8px;
  letter-spacing: 0.2em;
}

.panel-cap b {
  color: rgba(216, 233, 194, 0.45);
  font-weight: 400;
}

.objective-panel h2 {
  margin: 6px 0 3px;
  font-family: var(--sans);
  font-size: 20px;
  line-height: 1;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: #e4ebd2;
}

.objective-panel p {
  margin: 0;
  font-family: var(--sans);
  font-size: 11px;
  line-height: 1.25;
  color: rgba(207, 224, 185, 0.48);
}

.core-slots {
  display: flex;
  gap: 5px;
  margin-top: 9px;
}

.core-slot {
  position: relative;
  width: 30px;
  height: 16px;
  border: 1px solid rgba(179, 211, 135, 0.2);
  background: rgba(2, 8, 4, 0.45);
  clip-path: polygon(0 0, 100% 0, 100% 70%, 70% 100%, 0 100%);
}

.core-slot::after {
  content: 'LOST';
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: rgba(184, 207, 153, 0.27);
  font-size: 6px;
  letter-spacing: 0.1em;
}

.core-slot.found {
  border-color: var(--cyan);
  background: rgba(38, 93, 76, 0.4);
  box-shadow: inset 0 0 9px rgba(89, 236, 195, 0.18), 0 0 7px rgba(87, 229, 187, 0.1);
}

.core-slot.found::after {
  content: 'CORE';
  color: var(--cyan);
}

/* --------------------------------------------------------------------- */
/* Alert, vitals, threat                                                  */
/* --------------------------------------------------------------------- */

.alert-banner {
  position: absolute;
  top: 118px;
  left: 50%;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 7px 12px;
  transform: translate(-50%, -14px);
  opacity: 0;
  visibility: hidden;
  border: 1px solid rgba(235, 135, 83, 0.36);
  background: rgba(41, 11, 6, 0.78);
  color: #edb28b;
  backdrop-filter: blur(4px);
  transition: 0.25s ease;
  box-shadow: 0 0 26px rgba(150, 38, 11, 0.15);
}

.alert-banner.show {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, 0);
  animation: alertFlicker 0.5s steps(2);
}

@keyframes alertFlicker {
  0% { opacity: 0.3; }
  30% { opacity: 1; }
  50% { opacity: 0.5; }
  100% { opacity: 1; }
}

.alert-icon {
  font-family: var(--mono);
  font-size: 16px;
  letter-spacing: -0.1em;
}

.alert-banner div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.alert-banner b {
  font-size: 9px;
  letter-spacing: 0.14em;
}

.alert-banner small {
  font-size: 7px;
  letter-spacing: 0.12em;
  color: rgba(232, 168, 126, 0.54);
}

.alert-meter {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 15px;
  margin-left: 6px;
}

.alert-meter i {
  width: 2px;
  height: 40%;
  background: var(--red);
  animation: meterBounce 0.7s ease-in-out infinite alternate;
}

.alert-meter i:nth-child(2) { height: 80%; animation-delay: 0.1s; }
.alert-meter i:nth-child(3) { height: 55%; animation-delay: 0.18s; }
.alert-meter i:nth-child(4) { height: 100%; animation-delay: 0.06s; }
.alert-meter i:nth-child(5) { height: 65%; animation-delay: 0.22s; }

@keyframes meterBounce { to { transform: scaleY(0.35); } }

.vitals-panel {
  position: absolute;
  left: max(20px, env(safe-area-inset-left));
  bottom: max(22px, env(safe-area-inset-bottom));
  width: 265px;
  padding: 11px 12px 9px;
  border-left: 1px solid rgba(189, 219, 149, 0.3);
  background: linear-gradient(90deg, rgba(3, 10, 6, 0.72), rgba(3, 10, 6, 0.18));
  backdrop-filter: blur(2px);
  filter: drop-shadow(0 4px 9px rgba(0, 0, 0, 0.4));
}

.vital-row {
  display: grid;
  grid-template-columns: 54px 1fr 31px;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.vital-label {
  font-size: 7px;
  letter-spacing: 0.13em;
  color: rgba(203, 223, 179, 0.45);
}

.bar {
  position: relative;
  height: 4px;
  background: rgba(194, 219, 160, 0.12);
  overflow: hidden;
}

.bar i {
  display: block;
  height: 100%;
  width: 100%;
  transform-origin: left;
  transition: width 0.25s ease;
}

.bar.health i {
  background: linear-gradient(90deg, #9c2f20, #df6144);
  box-shadow: 0 0 8px rgba(214, 63, 40, 0.38);
}

.bar.stamina i {
  background: linear-gradient(90deg, #58782d, #c1dc70);
}

.bar.noise i {
  width: 18%;
  background: linear-gradient(90deg, #647f3f, #e6ca70);
}

.vital-row > b {
  font-size: 8px;
  font-weight: 400;
  text-align: right;
  letter-spacing: 0.08em;
  color: rgba(224, 237, 201, 0.7);
}

.vitals-foot {
  display: flex;
  justify-content: space-between;
  margin-top: 7px;
  padding-top: 7px;
  border-top: 1px solid rgba(187, 219, 148, 0.1);
  font-size: 7px;
  letter-spacing: 0.11em;
  color: rgba(197, 218, 173, 0.3);
}

.vitals-foot span:first-child {
  color: var(--moss);
}

.vitals-foot b { color: var(--moss-bright); font-weight: 400; }

.threat-panel {
  position: absolute;
  right: max(20px, env(safe-area-inset-right));
  bottom: max(22px, env(safe-area-inset-bottom));
  width: 222px;
  padding: 9px 10px 8px;
  border-right: 1px solid rgba(189, 219, 149, 0.25);
  background: linear-gradient(270deg, rgba(3, 10, 6, 0.78), rgba(3, 10, 6, 0.16));
  filter: drop-shadow(0 4px 9px rgba(0, 0, 0, 0.4));
}

.threat-head,
.threat-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 7px;
  letter-spacing: 0.12em;
  color: rgba(202, 225, 177, 0.43);
}

.threat-head i {
  width: 5px;
  height: 5px;
  background: rgba(201, 226, 172, 0.3);
}

.threat-head i.hot {
  background: var(--red);
  box-shadow: 0 0 8px var(--red);
  animation: blink 0.5s steps(1) infinite;
}

#proximity-canvas {
  display: block;
  width: 100%;
  height: 68px;
  margin: 4px 0 2px;
  image-rendering: pixelated;
  opacity: 0.85;
}

.threat-foot b {
  color: var(--moss-bright);
  font-weight: 400;
}

/* --------------------------------------------------------------------- */
/* Crosshair & interact                                                   */
/* --------------------------------------------------------------------- */

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 26px;
  height: 26px;
  transform: translate(-50%, -50%);
  opacity: 0.62;
  transition: opacity 0.2s;
}

.crosshair i {
  position: absolute;
  background: rgba(226, 238, 203, 0.85);
  box-shadow: 0 0 6px rgba(183, 233, 122, 0.3);
}

.crosshair i:nth-child(1) { width: 1px; height: 6px; left: 13px; top: 0; }
.crosshair i:nth-child(2) { width: 1px; height: 6px; left: 13px; bottom: 0; }
.crosshair i:nth-child(3) { width: 6px; height: 1px; left: 0; top: 13px; }
.crosshair i:nth-child(4) { width: 6px; height: 1px; right: 0; top: 13px; }

.crosshair span {
  position: absolute;
  left: 12px;
  top: 12px;
  width: 2px;
  height: 2px;
  border-radius: 50%;
  background: var(--acid);
}

.crosshair.hot i { background: var(--moss-bright); }

.interact-wrap {
  position: absolute;
  left: 50%;
  bottom: 22%;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 220px;
  padding: 8px 14px 8px 9px;
  transform: translate(-50%, 14px);
  opacity: 0;
  visibility: hidden;
  background: linear-gradient(90deg, rgba(8, 18, 10, 0.9), rgba(9, 22, 12, 0.5));
  border: 1px solid rgba(198, 227, 153, 0.28);
  transition: 0.2s ease;
  backdrop-filter: blur(4px);
}

.interact-wrap.show {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, 0);
}

.interact-wrap kbd {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  border: 1px solid rgba(204, 234, 153, 0.55);
  color: var(--moss-bright);
  font-family: var(--pixel);
  font-size: 10px;
  background: rgba(139, 180, 70, 0.13);
}

.interact-wrap div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.interact-wrap b {
  font-size: 9px;
  letter-spacing: 0.14em;
  color: #e1ebcd;
  font-weight: 400;
}

.interact-wrap span {
  font-size: 7px;
  letter-spacing: 0.12em;
  color: rgba(204, 225, 177, 0.45);
}

.controls-hint {
  position: absolute;
  left: 50%;
  bottom: max(22px, env(safe-area-inset-bottom));
  display: flex;
  gap: 17px;
  transform: translateX(-50%);
  font-size: 7px;
  letter-spacing: 0.08em;
  color: rgba(204, 224, 180, 0.26);
  white-space: nowrap;
}

.controls-hint kbd {
  color: rgba(214, 231, 191, 0.55);
  padding: 1px 3px;
  border: 1px solid rgba(198, 225, 159, 0.14);
}

/* --------------------------------------------------------------------- */
/* Toasts, subtitles                                                      */
/* --------------------------------------------------------------------- */

.toasts {
  position: absolute;
  left: 50%;
  top: 24%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  transform: translateX(-50%);
  width: min(440px, 84vw);
}

.toast {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 6px 11px;
  background: rgba(4, 12, 7, 0.8);
  border-left: 2px solid var(--moss);
  color: rgba(224, 236, 205, 0.78);
  font-size: 8px;
  letter-spacing: 0.12em;
  animation: toastIn 0.3s ease both;
  backdrop-filter: blur(3px);
}

.toast.warn { border-left-color: var(--amber); color: #e6c48c; }
.toast.danger { border-left-color: var(--red); color: #ed9c82; }
.toast.core { border-left-color: var(--cyan); color: var(--cyan); }
.toast::before { content: '>'; color: var(--moss); }

.toast.fade {
  animation: toastOut 0.4s ease forwards;
}

@keyframes toastIn {
  from { opacity: 0; transform: translateY(-7px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes toastOut {
  to { opacity: 0; transform: translateY(-5px); }
}

.subtitle {
  position: absolute;
  left: 50%;
  bottom: 13%;
  max-width: min(560px, 84vw);
  transform: translateX(-50%);
  text-align: center;
  font-family: var(--mono);
  font-size: 10px;
  line-height: 1.45;
  letter-spacing: 0.08em;
  color: rgba(224, 233, 203, 0.78);
  text-shadow: 0 2px 8px #000;
  opacity: 0;
  transition: opacity 0.4s;
}

.subtitle.show { opacity: 1; }

/* --------------------------------------------------------------------- */
/* Map                                                                    */
/* --------------------------------------------------------------------- */

.map-overlay {
  position: absolute;
  inset: 0;
  z-index: 55;
  display: grid;
  place-items: center;
  background: rgba(1, 5, 3, 0.78);
  backdrop-filter: blur(7px);
  opacity: 0;
  visibility: hidden;
  transition: 0.25s;
}

.map-overlay.show {
  opacity: 1;
  visibility: visible;
}

.map-frame {
  width: min(690px, 88vw);
  border: 1px solid rgba(186, 221, 139, 0.3);
  background: rgba(4, 12, 7, 0.94);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.8), 0 25px 80px rgba(0, 0, 0, 0.6);
}

.map-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 16px 18px 12px;
  border-bottom: 1px solid rgba(185, 218, 140, 0.15);
}

.map-head span {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.2em;
  color: var(--moss);
}

.map-head h2 {
  margin: 4px 0 0;
  font-family: var(--pixel);
  font-size: 17px;
  letter-spacing: 0.04em;
  color: #e2ecd0;
  font-weight: 400;
}

.map-close {
  padding: 6px 9px;
  border: 1px solid rgba(194, 223, 150, 0.26);
  background: transparent;
  color: rgba(221, 235, 200, 0.6);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  cursor: pointer;
}

.map-close:hover { border-color: var(--moss-bright); color: var(--moss-bright); }

.map-canvas-wrap {
  position: relative;
  margin: 14px;
  aspect-ratio: 1;
  background: #07110b;
  border: 1px solid rgba(186, 219, 141, 0.12);
  overflow: hidden;
}

#map-canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.map-scan {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(180deg, transparent 0, rgba(156, 222, 120, 0.07) 50%, transparent 51%);
  background-size: 100% 22%;
  animation: mapScan 5s linear infinite;
}

@keyframes mapScan { to { background-position-y: 100%; } }

.map-legend {
  position: absolute;
  left: 12px;
  bottom: 10px;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 6px 8px;
  background: rgba(3, 9, 5, 0.78);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  color: rgba(212, 231, 190, 0.55);
}

.map-legend span { display: flex; align-items: center; gap: 5px; }

.map-legend i { width: 5px; height: 5px; display: inline-block; }
.lg-you { background: var(--acid); }
.lg-core { background: var(--cyan); }
.lg-lab { background: var(--steel); }
.lg-contact { background: var(--red); }

.map-foot {
  display: flex;
  justify-content: space-between;
  padding: 0 18px 14px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  color: rgba(206, 225, 180, 0.35);
}

/* --------------------------------------------------------------------- */
/* End states & pause                                                     */
/* --------------------------------------------------------------------- */

.pause-overlay,
.end-overlay {
  position: absolute;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle at 50% 50%, rgba(9, 20, 12, 0.38), rgba(1, 5, 3, 0.9)),
    repeating-linear-gradient(0deg, transparent 0 2px, rgba(0, 0, 0, 0.18) 3px);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.4s ease, visibility 0.4s;
}

.pause-overlay.show,
.end-overlay.show {
  opacity: 1;
  visibility: visible;
}

.pause-box {
  width: min(360px, 84vw);
  padding: 27px;
  text-align: center;
  border: 1px solid rgba(187, 220, 141, 0.3);
  background: rgba(4, 12, 7, 0.9);
}

.pause-box .eyebrow { justify-content: center; }
.pause-box h2 {
  margin: 9px 0 4px;
  font-family: var(--pixel);
  font-weight: 400;
  font-size: 30px;
  color: #e0ebcd;
}
.pause-box p {
  margin: 0 0 20px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  color: rgba(208, 226, 184, 0.5);
}

.pause-box button,
.end-content button {
  display: block;
  width: 100%;
  margin-top: 8px;
  padding: 10px;
  border: 1px solid rgba(196, 226, 147, 0.45);
  background: rgba(117, 154, 60, 0.18);
  color: #dfecc8;
  font-family: var(--pixel);
  font-size: 9px;
  letter-spacing: 0.08em;
  cursor: pointer;
  transition: 0.2s;
}

.pause-box button:hover,
.end-content button:hover {
  background: var(--moss-bright);
  color: #071006;
}

.pause-box button.ghost {
  background: transparent;
  border-color: rgba(196, 226, 147, 0.16);
  color: rgba(218, 232, 196, 0.45);
}

.end-content {
  width: min(520px, 88vw);
  text-align: center;
  padding: 20px;
}

.end-kicker {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.3em;
  color: var(--red);
}

.end-overlay.win .end-kicker { color: var(--cyan); }

.end-content h2 {
  margin: 10px 0 13px;
  font-family: var(--pixel);
  font-size: clamp(36px, 5.8vw, 66px);
  line-height: 0.92;
  font-weight: 400;
  letter-spacing: -0.05em;
  color: #e4ecd4;
  text-shadow: 4px 4px 0 rgba(0, 0, 0, 0.5);
}

.end-overlay.death .end-content h2 {
  color: #d88772;
  text-shadow: 3px 0 rgba(58, 7, 4, 0.8), -3px 0 rgba(56, 22, 12, 0.8);
}

.end-content p {
  margin: 0 auto 22px;
  max-width: 330px;
  font-family: var(--mono);
  font-size: 10px;
  line-height: 1.6;
  letter-spacing: 0.08em;
  color: rgba(217, 230, 195, 0.5);
}

.end-content button { width: min(280px, 100%); margin: 0 auto; }

.win-stats {
  display: flex;
  justify-content: center;
  gap: 23px;
  margin: 0 0 22px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  color: rgba(214, 230, 190, 0.45);
}

.win-stats b {
  display: block;
  margin-top: 3px;
  font-family: var(--pixel);
  color: var(--cyan);
  font-size: 13px;
  font-weight: 400;
}

.screen-fade {
  position: absolute;
  inset: 0;
  z-index: 80;
  pointer-events: none;
  background: #010403;
  opacity: 0;
  transition: opacity 0.6s ease;
}

.screen-fade.black { opacity: 1; }

/* --------------------------------------------------------------------- */
/* Touch                                                                  */
/* --------------------------------------------------------------------- */

.touch-controls {
  display: none;
}

@media (pointer: coarse), (max-width: 820px) {
  .touch-controls {
    display: block;
    position: absolute;
    inset: 0;
    pointer-events: none;
  }

  .joy-zone {
    position: absolute;
    left: max(22px, env(safe-area-inset-left));
    bottom: max(118px, calc(env(safe-area-inset-bottom) + 96px));
    width: 112px;
    height: 112px;
    border: 1px solid rgba(198, 227, 150, 0.2);
    border-radius: 50%;
    background: radial-gradient(circle, rgba(148, 186, 90, 0.08), transparent 68%);
    pointer-events: auto;
    touch-action: none;
  }

  .joy-zone::before,
  .joy-zone::after {
    content: '';
    position: absolute;
    background: rgba(199, 227, 154, 0.12);
  }
  .joy-zone::before { left: 50%; top: 12px; bottom: 12px; width: 1px; }
  .joy-zone::after { top: 50%; left: 12px; right: 12px; height: 1px; }

  .joy-zone span {
    position: absolute;
    left: 50%;
    bottom: -15px;
    transform: translateX(-50%);
    font-size: 6px;
    letter-spacing: 0.15em;
    color: rgba(206, 228, 180, 0.3);
  }

  .joy-knob {
