      px(ctx, rng.int(0, w - 1), rng.int(0, h - 1), rng.int(1, 3), rng.int(1, 2), rng.pick(['#695b3d', '#332d22', '#806a43', '#583f27']));
    }
    ctx.globalAlpha = 0.3;
    for (let i = 0; i < 20; i += 1) px(ctx, rng.int(0, w), rng.int(0, h), 1, rng.int(2, 8), '#18140e');
