export function coreTexture() {
  return makeTexture('core', 32, 32, (ctx, w, h) => {
    px(ctx, 0, 0, w, h, '#0a201b');
    px(ctx, 11, 4, 10, 24, '#6be7c5');
    px(ctx, 13, 6, 6, 20, '#b4ffea');
    px(ctx, 8, 10, 16, 12, '#41bfa1');
    for (let y = 3; y < 29; y += 5) px(ctx, 9, y, 14, 1, '#d3fff2');
    for (let x = 6; x < 27; x += 5) px(ctx, x, 9, 1, 14, '#2c9d84');
  }, { repeat: [1, 1], wrap: false });
}

export function makeTextTexture(text, options = {}) {
  const value = String(text);
  const w = options.width ?? 256;
  const h = options.height ?? 64;
  const color = options.color ?? '#d8e4b5';
  const bg = options.bg ?? '#0b1510';
  const size = options.size ?? 18;
  return makeTexture(`text:${value}:${w}:${h}:${color}:${bg}:${size}`, w, h, (ctx) => {
    px(ctx, 0, 0, w, h, bg);
    ctx.fillStyle = color;
    ctx.font = `bold ${size}px monospace`;
    ctx.textAlign = options.align ?? 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(value, options.align === 'left' ? 10 : w / 2, h / 2);
    if (options.subtle) {
      ctx.fillStyle = 'rgba(255,255,255,.06)';
      for (let y = 0; y < h; y += 4) ctx.fillRect(0, y, w, 1);
    }
  }, { repeat: [1, 1], wrap: false });
}

export function disposeTextures() {
  for (const texture of textureCache.values()) texture.dispose();
  textureCache.clear();
}

export { clamp };

import { clamp, randRange } from './utils.js';

/**
 * Fully procedural WebAudio soundscape. No sample files: every footstep,
 * hydraulic hiss, insect chirp and growl is synthesized in the browser.
 */
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.ready = false;
    this.master = null;
    this.musicBus = null;
    this.fxBus = null;
    this.reverb = null;
    this.noiseBuffer = null;
    this.ambient = {};
    this.inside = true;
    this.nextBug = 1.5;
    this.growlCooldown = 0;
    this.heartCooldown = 0;
    this.dead = false;
    this.muted = false;
  }

  async init() {
    if (this.ready) {
      if (this.ctx.state === 'suspended') await this.ctx.resume();
      return;
    }
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    this.ctx = new AudioCtx();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.78;
    const limiter = this.ctx.createDynamicsCompressor();
    limiter.threshold.value = -14;
    limiter.knee.value = 22;
    limiter.ratio.value = 4;
    limiter.attack.value = 0.004;
    limiter.release.value = 0.24;
    this.master.connect(limiter);
    limiter.connect(this.ctx.destination);

    this.musicBus = this.ctx.createGain();
    this.musicBus.gain.value = 0.8;
    this.musicBus.connect(this.master);
    this.fxBus = this.ctx.createGain();
    this.fxBus.gain.value = 0.95;
    this.fxBus.connect(this.master);

    await this.buildReverb();
    this.noiseBuffer = this.createNoiseBuffer(4);
    this.startAmbience();
    this.ready = true;
    if (this.ctx.state === 'suspended') await this.ctx.resume();
  }

  async buildReverb() {
    const len = this.ctx.sampleRate * 2.5;
    const impulse = this.ctx.createBuffer(2, len, this.ctx.sampleRate);
    for (let channel = 0; channel < 2; channel += 1) {
      const data = impulse.getChannelData(channel);
      for (let i = 0; i < len; i += 1) {
        const t = i / len;
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, 3.7) * 0.58;
      }
    }
    this.reverb = this.ctx.createConvolver();
    this.reverb.buffer = impulse;
    const wet = this.ctx.createGain();
    wet.gain.value = 0.24;
    this.reverb.connect(wet);
    wet.connect(this.master);
  }

  createNoiseBuffer(seconds = 2) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i += 1) {
      const white = Math.random() * 2 - 1;
      last = 0.985 * last + 0.015 * white;
      data[i] = white * 0.6 + last * 1.8;
    }
    return buffer;
  }

  noiseSource(duration = 1, loop = false) {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = loop;
    src.playbackRate.value = randRange(Math.random, 0.92, 1.06);
    if (!loop) src.start(this.ctx.currentTime, Math.random() * 2, duration);
    return src;
  }

  startAmbience() {
    const t = this.ctx.currentTime;
    const makeDrone = (freq, gain, type) => {
      const osc = this.ctx.createOscillator();
      const g = this.ctx.createGain();
      osc.type = type;
      osc.frequency.value = freq;
      g.gain.value = 0;
      osc.connect(g);
      g.connect(this.musicBus);
      osc.start(t);
      return { osc, gain: g };
    };
    this.ambient.drone1 = makeDrone(41, 0.035, 'sine');
    this.ambient.drone2 = makeDrone(57.8, 0.018, 'triangle');
    this.ambient.drone3 = makeDrone(82.4, 0.009, 'sine');

    // Outdoor wind: filtered noise.
    const wind = this.noiseSource(1, true);
    const windFilter = this.ctx.createBiquadFilter();
    windFilter.type = 'lowpass';
    windFilter.frequency.value = 460;
    windFilter.Q.value = 0.4;
    const windGain = this.ctx.createGain();
    windGain.gain.value = 0;
    wind.connect(windFilter);
    windFilter.connect(windGain);
    windGain.connect(this.musicBus);
    wind.start(t);
    this.ambient.wind = { source: wind, gain: windGain, filter: windFilter };

    // Interior ventilation rumble.
    const vent = this.ctx.createOscillator();
    const ventG = this.ctx.createGain();
    vent.type = 'sawtooth';
    vent.frequency.value = 31;
    ventG.gain.value = 0;
    vent.connect(ventG);
    ventG.connect(this.musicBus);
    vent.start(t);
    this.ambient.vent = { osc: vent, gain: ventG };

    // Slow LFO breathing on wind.
    const lfo = this.ctx.createOscillator();
    const lfoGain = this.ctx.createGain();
    lfo.frequency.value = 0.075;
    lfoGain.gain.value = 120;
    lfo.connect(lfoGain);
    lfoGain.connect(windFilter.frequency);
    lfo.start(t);
    this.ambient.lfo = lfo;

    this.setEnvironment(true, true);
  }

  setEnvironment(inside, instant = false) {
    if (!this.ready) return;
    this.inside = inside;
    const now = this.ctx.currentTime;
    const time = instant ? 0.01 : 2.2;
    const set = (param, value) => {
      param.cancelScheduledValues(now);
      param.setTargetAtTime(value, now, time / 3);
    };
    set(this.ambient.drone1.gain.gain, inside ? 0.035 : 0.018);
    set(this.ambient.drone2.gain.gain, inside ? 0.018 : 0.011);
    set(this.ambient.drone3.gain.gain, inside ? 0.009 : 0.006);
    set(this.ambient.wind.gain.gain, inside ? 0.012 : 0.052);
    set(this.ambient.vent.gain.gain, inside ? 0.011 : 0.001);
  }

  setMuted(muted) {
    this.muted = muted;
    if (!this.ready) return;
    this.master.gain.setTargetAtTime(muted ? 0 : 0.78, this.ctx.currentTime, 0.1);
  }

  update(dt, state = {}) {
    if (!this.ready || this.dead) return;
    this.nextBug -= dt;
    if (!this.inside && this.nextBug <= 0) {
      this.bugChirp();
      this.nextBug = randRange(Math.random, 1.1, 5.2);
    }
    this.growlCooldown -= dt;
    if (state.threat > 0.35 && this.growlCooldown <= 0) {
      this.growl(state.threat * (state.distance ? clamp(1 - state.distance / 95, 0.1, 1) : 1));
      this.growlCooldown = randRange(Math.random, 3.4, 6.8);
    }
    this.heartCooldown -= dt;
    if (state.heart > 0.1 && this.heartCooldown <= 0) {
      this.heartbeat(state.heart);
      this.heartCooldown = 0.86 - state.heart * 0.28;
    }
  }

  bugChirp() {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const pan = this.ctx.createStereoPanner();
    osc.type = 'sine';
    const base = randRange(Math.random, 2800, 4900);
    osc.frequency.setValueAtTime(base, now);
    osc.frequency.setValueAtTime(base * 1.28, now + 0.035);
    osc.frequency.setValueAtTime(base * 0.9, now + 0.07);
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(randRange(Math.random, 0.003, 0.011), now + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.11);
    pan.pan.value = randRange(Math.random, -0.9, 0.9);
    osc.connect(gain);
    gain.connect(pan);
    pan.connect(this.fxBus);
    osc.start(now);
    osc.stop(now + 0.13);
  }

  footstep(surface = 'dirt', intensity = 1) {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.playbackRate.value = randRange(Math.random, 0.7, 1.16);
    const filter = this.ctx.createBiquadFilter();
    filter.type = surface === 'metal' ? 'bandpass' : 'lowpass';
    filter.frequency.value = surface === 'metal' ? randRange(Math.random, 480, 900) : randRange(Math.random, 260, 430);
    filter.Q.value = surface === 'metal' ? 1.2 : 0.6;
    const gain = this.ctx.createGain();
    const level = 0.07 * intensity;
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(level, now + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.14);
    src.connect(filter);
    filter.connect(gain);
    gain.connect(this.fxBus);
    gain.connect(this.reverb);
    src.start(now, Math.random() * 2, 0.16);
    if (surface === 'metal') {
      const ping = this.ctx.createOscillator();
      const pg = this.ctx.createGain();
      ping.type = 'sine';
      ping.frequency.value = randRange(Math.random, 140, 240);
      pg.gain.setValueAtTime(level * 0.22, now);
      pg.gain.exponentialRampToValueAtTime(0.0001, now + 0.2);
      ping.connect(pg);
      pg.connect(this.fxBus);
      ping.start(now);
      ping.stop(now + 0.22);
    }
  }

  hydraulic(open = true) {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    const duration = 2.5;
    // Pressurized hiss.
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const bp = this.ctx.createBiquadFilter();
    bp.type = 'bandpass';
    bp.frequency.setValueAtTime(open ? 1800 : 1100, now);
    bp.frequency.linearRampToValueAtTime(open ? 2600 : 1800, now + 0.4);
    bp.frequency.exponentialRampToValueAtTime(open ? 700 : 950, now + duration);
    bp.Q.value = 0.7;
    const hissGain = this.ctx.createGain();
    hissGain.gain.setValueAtTime(0, now);
    hissGain.gain.linearRampToValueAtTime(0.055, now + 0.06);
    hissGain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    src.connect(bp);
    bp.connect(hissGain);
    hissGain.connect(this.fxBus);
    hissGain.connect(this.reverb);
    src.start(now, Math.random() * 2);
    src.stop(now + duration + 0.1);

    // Low hydraulic motor.
    const motor = this.ctx.createOscillator();
    const motorGain = this.ctx.createGain();
    motor.type = 'sawtooth';
    motor.frequency.setValueAtTime(open ? 38 : 46, now);
    motor.frequency.linearRampToValueAtTime(open ? 52 : 62, now + 0.8);
    motor.frequency.linearRampToValueAtTime(open ? 42 : 48, now + duration);
    motorGain.gain.setValueAtTime(0, now);
    motorGain.gain.linearRampToValueAtTime(0.025, now + 0.15);
    motorGain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    const lp = this.ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 210;
    motor.connect(lp);
    lp.connect(motorGain);
    motorGain.connect(this.fxBus);
    motor.start(now);
    motor.stop(now + duration);

    // End clunk.
    const clunk = this.ctx.createOscillator();
    const cg = this.ctx.createGain();
    clunk.type = 'triangle';
    clunk.frequency.setValueAtTime(72, now + duration - 0.18);
    clunk.frequency.exponentialRampToValueAtTime(32, now + duration);
    cg.gain.setValueAtTime(0, now + duration - 0.2);
    cg.gain.linearRampToValueAtTime(0.09, now + duration - 0.15);
    cg.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    clunk.connect(cg);
    cg.connect(this.fxBus);
    clunk.start(now + duration - 0.22);
    clunk.stop(now + duration + 0.05);
  }

  switchClick() {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'square';
    osc.frequency.setValueAtTime(900, now);
    osc.frequency.exponentialRampToValueAtTime(180, now + 0.035);
    gain.gain.setValueAtTime(0.04, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.06);
    osc.connect(gain);
    gain.connect(this.fxBus);
    osc.start(now);
    osc.stop(now + 0.07);
  }

  pickup() {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    [523.25, 659.25, 783.99, 1046.5].forEach((f, i) => {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = i % 2 ? 'sine' : 'triangle';
      osc.frequency.value = f;
      const at = now + i * 0.07;
      gain.gain.setValueAtTime(0, at);
      gain.gain.linearRampToValueAtTime(0.04, at + 0.01);
      gain.gain.exponentialRampToValueAtTime(0.0001, at + 0.45);
      osc.connect(gain);
      gain.connect(this.fxBus);
      osc.start(at);
      osc.stop(at + 0.5);
    });
  }

  terminal() {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    for (let i = 0; i < 3; i += 1) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'square';
      osc.frequency.value = 880 + i * 220;
      const at = now + i * 0.12;
      gain.gain.setValueAtTime(0.018, at);
      gain.gain.exponentialRampToValueAtTime(0.0001, at + 0.09);
      osc.connect(gain);
      gain.connect(this.fxBus);
      osc.start(at);
      osc.stop(at + 0.1);
    }
  }

  heartbeat(intensity = 1) {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    for (let i = 0; i < 2; i += 1) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sine';
      const at = now + i * 0.15;
      osc.frequency.setValueAtTime(55, at);
      osc.frequency.exponentialRampToValueAtTime(32, at + 0.14);
      gain.gain.setValueAtTime(0, at);
      gain.gain.linearRampToValueAtTime(0.04 * intensity, at + 0.015);
      gain.gain.exponentialRampToValueAtTime(0.0001, at + 0.3);
      osc.connect(gain);
      gain.connect(this.fxBus);
      osc.start(at);
      osc.stop(at + 0.34);
    }
  }

  growl(intensity = 0.7) {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const osc2 = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();
    osc.type = 'sawtooth';
    osc2.type = 'square';
    osc.frequency.setValueAtTime(34 + Math.random() * 9, now);
    osc.frequency.linearRampToValueAtTime(46 + Math.random() * 8, now + 0.5);
    osc.frequency.linearRampToValueAtTime(31, now + 1.2);
    osc2.frequency.value = 51;
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(180, now);
    filter.frequency.linearRampToValueAtTime(380, now + 0.35);
    filter.frequency.linearRampToValueAtTime(130, now + 1.2);
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.035 * intensity, now + 0.12);
    gain.gain.linearRampToValueAtTime(0.02 * intensity, now + 0.7);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 1.3);
    osc.connect(filter);
    osc2.connect(filter);
    filter.connect(gain);
    gain.connect(this.fxBus);
    gain.connect(this.reverb);
    osc.start(now);
    osc2.start(now);
    osc.stop(now + 1.32);
    osc2.stop(now + 1.32);
  }

  roar() {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const osc2 = this.ctx.createOscillator();
    const noise = this.ctx.createBufferSource();
    noise.buffer = this.noiseBuffer;
    const noiseFilter = this.ctx.createBiquadFilter();
    noiseFilter.type = 'bandpass';
    noiseFilter.frequency.value = 420;
    noiseFilter.Q.value = 0.8;
    const noiseGain = this.ctx.createGain();
    noiseGain.gain.setValueAtTime(0.06, now);
    noiseGain.gain.exponentialRampToValueAtTime(0.0001, now + 1.3);
    noise.connect(noiseFilter);
    noiseFilter.connect(noiseGain);
    noiseGain.connect(this.fxBus);

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(1100, now);
    filter.frequency.exponentialRampToValueAtTime(270, now + 1.1);
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.12, now + 0.06);
    gain.gain.linearRampToValueAtTime(0.09, now + 0.8);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 1.5);
    osc.type = 'sawtooth';
    osc2.type = 'square';
    osc.frequency.setValueAtTime(58, now);
    osc.frequency.linearRampToValueAtTime(88, now + 0.2);
    osc.frequency.linearRampToValueAtTime(42, now + 1.2);
    osc2.frequency.setValueAtTime(70, now);
    osc2.frequency.linearRampToValueAtTime(106, now + 0.2);
    osc2.frequency.linearRampToValueAtTime(50, now + 1.2);
    osc.connect(filter);
    osc2.connect(filter);
    filter.connect(gain);
    gain.connect(this.fxBus);
    gain.connect(this.reverb);
    osc.start(now);
    osc2.start(now);
    noise.start(now, Math.random(), 1.5);
    osc.stop(now + 1.55);
    osc2.stop(now + 1.55);
  }

  impact() {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(110, now);
    osc.frequency.exponentialRampToValueAtTime(32, now + 0.4);
    filter.type = 'lowpass';
    filter.frequency.value = 380;
    gain.gain.setValueAtTime(0.16, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.55);
    osc.connect(filter);
    filter.connect(gain);
    gain.connect(this.fxBus);
    osc.start(now);
    osc.stop(now + 0.58);
    const noise = this.noiseSource(0.34);
    const nf = this.ctx.createBiquadFilter();
    nf.type = 'lowpass';
    nf.frequency.value = 1000;
    const ng = this.ctx.createGain();
    ng.gain.value = 0.12;
    noise.connect(nf);
    nf.connect(ng);
    ng.connect(this.fxBus);
  }

  ui(up = true) {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'square';
    osc.frequency.value = up ? 660 : 420;
    gain.gain.setValueAtTime(0.012, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.06);
    osc.connect(gain);
    gain.connect(this.fxBus);
    osc.start(now);
    osc.stop(now + 0.07);
  }

  alarm() {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    for (let i = 0; i < 2; i += 1) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(320, now + i * 0.48);
      osc.frequency.linearRampToValueAtTime(620, now + i * 0.48 + 0.28);
      osc.frequency.linearRampToValueAtTime(320, now + i * 0.48 + 0.46);
      const filter = this.ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 1200;
      gain.gain.setValueAtTime(0.03, now + i * 0.48);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + i * 0.48 + 0.46);
      osc.connect(filter);
      filter.connect(gain);
      gain.connect(this.fxBus);
      osc.start(now + i * 0.48);
      osc.stop(now + i * 0.48 + 0.48);
    }
  }

  death() {
    if (!this.ready) return;
    this.dead = true;
    this.roar();
    const now = this.ctx.currentTime;
    this.master.gain.cancelScheduledValues(now);
    this.master.gain.setValueAtTime(0.78, now);
    this.master.gain.exponentialRampToValueAtTime(0.0001, now + 3.2);
    this.ambient.drone1.gain.gain.setTargetAtTime(0.001, now, 0.6);
    this.ambient.wind.gain.gain.setTargetAtTime(0.001, now, 0.6);
  }

  victory() {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    [329.63, 392, 493.88, 659.25, 783.99].forEach((f, i) => {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.value = f;
      const at = now + i * 0.16;
      gain.gain.setValueAtTime(0, at);
      gain.gain.linearRampToValueAtTime(0.035, at + 0.04);
      gain.gain.exponentialRampToValueAtTime(0.0001, at + 1.2);
      osc.connect(gain);
      gain.connect(this.fxBus);
      osc.start(at);
      osc.stop(at + 1.3);
    });
  }

  reset() {
    this.dead = false;
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    this.master.gain.cancelScheduledValues(now);
    this.master.gain.setTargetAtTime(0.78, now, 0.2);
    this.setEnvironment(true, true);
  }
}

import * as THREE from 'three';
import {
  barkTexture,
  ceilingTexture,
  containerTexture,
  coreTexture,
  crateTexture,
  hazardTexture,
  makeTextTexture,
  metalFloorTexture,
  metalPanelTexture,
  metalWallTexture,
  rustTexture,
  screenTexture,
  warningTexture,
} from './textures.js';
import { clamp, easeInOutCubic } from './utils.js';

const _v = new THREE.Vector3();

function box(parent, {
  w = 1, h = 1, d = 1, x = 0, y = 0, z = 0, material, cast = true, receive = true, rotY = 0,
}) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
  mesh.position.set(x, y, z);
  mesh.rotation.y = rotY;
  mesh.castShadow = cast;
  mesh.receiveShadow = receive;
  parent.add(mesh);
  return mesh;
}

function plane(parent, {
  w = 1, h = 1, x = 0, y = 0, z = 0, material, rotX = 0, rotY = 0, rotZ = 0,
}) {
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, h), material);
  mesh.position.set(x, y, z);
  mesh.rotation.set(rotX, rotY, rotZ);
  parent.add(mesh);
  return mesh;
}

export class Laboratory {
  constructor(scene, callbacks = {}) {
    this.scene = scene;
    this.callbacks = callbacks;
    this.group = new THREE.Group();
    this.group.name = 'LaboratoryLobby';
    scene.add(this.group);
    this.doors = [];
    this.interactables = [];
    this.colliders = [];
    this.emissives = [];
    this.lights = [];
    this.elapsed = 0;
    this.materials = this.createMaterials();
    this.buildRoom();
    this.buildDoors();
    this.buildLabDetails();
    this.buildTerminal();
  }

  createMaterials() {
    const wall = metalWallTexture();
    const floor = metalFloorTexture();
    const ceiling = ceilingTexture();
    const hazard = hazardTexture();
    const panel = metalPanelTexture();
    const rust = rustTexture();
    const warning = warningTexture();

    return {
      wall: new THREE.MeshStandardMaterial({ map: wall, color: 0x9ba79e, roughness: 0.82, metalness: 0.48 }),
      wallDark: new THREE.MeshStandardMaterial({ map: wall, color: 0x65726a, roughness: 0.8, metalness: 0.42 }),
      floor: new THREE.MeshStandardMaterial({ map: floor, color: 0xa3aea4, roughness: 0.72, metalness: 0.5 }),
      ceiling: new THREE.MeshStandardMaterial({ map: ceiling, color: 0x7f8c83, roughness: 0.9, metalness: 0.2 }),
      trim: new THREE.MeshStandardMaterial({ color: 0x101a16, roughness: 0.65, metalness: 0.55 }),
      steel: new THREE.MeshStandardMaterial({ map: panel, color: 0x9aaba1, roughness: 0.46, metalness: 0.8 }),
      steelDark: new THREE.MeshStandardMaterial({ color: 0x26332d, roughness: 0.48, metalness: 0.72 }),
      rust: new THREE.MeshStandardMaterial({ map: rust, color: 0x9b8d73, roughness: 0.94, metalness: 0.22 }),
      hazard: new THREE.MeshStandardMaterial({ map: hazard, color: 0xe0c758, roughness: 0.8, metalness: 0.25 }),
      warning: new THREE.MeshBasicMaterial({ map: warning, color: 0xd5bb59, transparent: false }),
      crate: new THREE.MeshStandardMaterial({ map: crateTexture(), color: 0xad9872, roughness: 0.93 }),
      container: new THREE.MeshStandardMaterial({ map: containerTexture(), color: 0xbab073, roughness: 0.7, metalness: 0.35 }),
      glass: new THREE.MeshPhysicalMaterial({
        color: 0x9ed6bc,
        transparent: true,
        opacity: 0.22,
        roughness: 0.15,
        metalness: 0.1,
        transmission: 0.24,
        side: THREE.DoubleSide,
      }),
      screen0: new THREE.MeshBasicMaterial({ map: screenTexture(0), toneMapped: false }),
      screen1: new THREE.MeshBasicMaterial({ map: screenTexture(1), toneMapped: false }),
      screen2: new THREE.MeshBasicMaterial({ map: screenTexture(2), toneMapped: false }),
      cyanGlow: new THREE.MeshBasicMaterial({ color: 0x79ffe0, toneMapped: false }),
      greenGlow: new THREE.MeshBasicMaterial({ color: 0x9fe36a, toneMapped: false }),
      amberGlow: new THREE.MeshBasicMaterial({ color: 0xffb35c, toneMapped: false }),
      redGlow: new THREE.MeshBasicMaterial({ color: 0xff5038, toneMapped: false }),
      fluid: new THREE.MeshStandardMaterial({
        color: 0x5bc992,
        emissive: 0x2fae75,
        emissiveIntensity: 0.9,
        transparent: true,
        opacity: 0.55,
        roughness: 0.25,
        metalness: 0.1,
      }),
      cable: new THREE.MeshStandardMaterial({ color: 0x121c17, roughness: 0.9 }),
      paper: new THREE.MeshStandardMaterial({ map: makeTextTexture('M-08', { width: 128, height: 64, size: 21, color: '#22301f', bg: '#cfc9a3' }), roughness: 1 }),
      screenLabel: [
        'SECTOR 09 // LOBBY',
        'AUTHORIZED PERSONNEL ONLY',
        'CONTAINMENT PROTOCOL',
        'BIOHAZARD LEVEL 5',
      ].map((text) => new THREE.MeshBasicMaterial({
        map: makeTextTexture(text, { width: 512, height: 80, size: 30, color: '#c4d9a0', bg: '#07100a', subtle: true }),
        toneMapped: false,
      })),
    };
  }

  buildRoom() {
    const m = this.materials;
    const wallH = 4.5;
    const half = 7.5;
    const thick = 0.32;
    const doorW = 3.15;

    // Floor and ceiling.
    box(this.group, { w: 15, h: 0.16, d: 15, y: -0.08, material: m.floor, cast: false });
    box(this.group, { w: 15, h: 0.2, d: 15, y: wallH + 0.1, material: m.ceiling, cast: false });
    this.buildFloorMarkings();

    const wallPositions = [
      { axis: 'x', sign: -1, center: -half, len: 15, door: 'N' },
      { axis: 'x', sign: 1, center: half, len: 15, door: 'S' },
      { axis: 'z', sign: -1, center: -half, len: 15, door: 'W' },
      { axis: 'z', sign: 1, center: half, len: 15, door: 'E' },
    ];

    // For north/south walls the long axis is X. For east/west it is Z.
    for (const doorAxis of ['N', 'S', 'E', 'W']) {
      const northSouth = doorAxis === 'N' || doorAxis === 'S';
      const sideLen = (15 - doorW) / 2;
      const sign = (doorAxis === 'N' || doorAxis === 'W') ? -1 : 1;
      const offset = sign * half;
      for (const dir of [-1, 1]) {
        const center = dir * (doorW / 2 + sideLen / 2);
        if (northSouth) {
          box(this.group, { w: sideLen, h: wallH, d: thick, x: center, y: wallH / 2, z: offset, material: m.wall });
          this.colliders.push({ minX: center - sideLen / 2, maxX: center + sideLen / 2, minZ: offset - thick / 2, maxZ: offset + thick / 2, kind: 'wall' });
        } else {
          box(this.group, { w: thick, h: wallH, d: sideLen, x: offset, y: wallH / 2, z: center, material: m.wall });
          this.colliders.push({ minX: offset - thick / 2, maxX: offset + thick / 2, minZ: center - sideLen / 2, maxZ: center + sideLen / 2, kind: 'wall' });
        }
      }
      // Header above the door.
      if (northSouth) {
        box(this.group, { w: doorW, h: wallH - 3.65, d: thick, x: 0, y: 3.65 + (wallH - 3.65) / 2, z: offset, material: m.wallDark });
      } else {
        box(this.group, { w: thick, h: wallH - 3.65, d: doorW, x: offset, y: 3.65 + (wallH - 3.65) / 2, z: 0, material: m.wallDark });
      }
      // Wall base trim.
      for (const dir of [-1, 1]) {
        const center = dir * (doorW / 2 + sideLen / 2);
        if (northSouth) {
          box(this.group, { w: sideLen, h: 0.22, d: 0.39, x: center, y: 0.11, z: offset, material: m.trim });
          box(this.group, { w: sideLen, h: 0.1, d: 0.38, x: center, y: 3.38, z: offset, material: m.hazard });
        } else {
          box(this.group, { w: 0.39, h: 0.22, d: sideLen, x: offset, y: 0.11, z: center, material: m.trim });
          box(this.group, { w: 0.38, h: 0.1, d: sideLen, x: offset, y: 3.38, z: center, material: m.hazard });
        }
      }
    }

    // Structural ribs.
    for (let i = -3; i <= 3; i += 1) {
      const x = i * 2.15;
      const z = i * 2.15;
      if (Math.abs(x) > 6.3 || Math.abs(z) > 6.3) continue;
      box(this.group, { w: 0.1, h: 0.08, d: 14.5, x, y: 4.35, z: 0, material: m.trim, cast: false });
    }

    // Ceiling light housings.
    const housingMat = m.steelDark;
    for (const z of [-3.7, 0, 3.7]) {
      box(this.group, { w: 5.2, h: 0.12, d: 0.56, x: 0, y: 4.37, z, material: housingMat, cast: false });
      const glow = box(this.group, { w: 4.95, h: 0.055, d: 0.34, x: 0, y: 4.285, z, material: m.cyanGlow, cast: false, receive: false });
      this.emissives.push(glow);
    }
    // Pipes.
    for (const x of [-6.4, -5.9, 6.1, 6.6]) {
      const pipe = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.075, 14.4, 6), m.steelDark);
      pipe.rotation.x = Math.PI / 2;
      pipe.position.set(x, 4.13, 0);
      pipe.castShadow = true;
      this.group.add(pipe);
    }
    for (const z of [-6.3, -5.8, 5.9]) {
      const pipe = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.055, 14.4, 5), m.rust);
      pipe.rotation.z = Math.PI / 2;
      pipe.position.set(0, 4.16, z);
      this.group.add(pipe);
    }

    // Wall displays and labels.
    const labelA = plane(this.group, {
      w: 2.4, h: 0.38, x: -4.2, y: 3.62, z: -7.32,
      material: m.screenLabel[0],
    });
    labelA.rotation.y = 0;
    plane(this.group, { w: 0.92, h: 0.92, x: -6.95, y: 2.45, z: -4.9, material: m.warning, rotY: Math.PI / 2 });
    plane(this.group, { w: 1.8, h: 0.34, x: 4.5, y: 3.62, z: -7.32, material: m.screenLabel[1] });
    plane(this.group, { w: 1.8, h: 0.34, x: -4.4, y: 3.62, z: 7.32, material: m.screenLabel[2], rotY: Math.PI });
    plane(this.group, { w: 1.7, h: 0.32, x: 7.32, y: 3.62, z: -4.1, material: m.screenLabel[3], rotY: -Math.PI / 2 });
    plane(this.group, { w: 1.3, h: 0.3, x: -7.32, y: 2.95, z: 4.4, material: m.screenLabel[1], rotY: Math.PI / 2 });

    this.addLighting();
  }

  buildFloorMarkings() {
    const m = this.materials;
    const ringMat = new THREE.MeshBasicMaterial({ color: 0x8a9d54, transparent: true, opacity: 0.28, side: THREE.DoubleSide });
    const ring = new THREE.Mesh(new THREE.RingGeometry(2.55, 2.63, 48), ringMat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.008;
    this.group.add(ring);
    const ring2 = new THREE.Mesh(new THREE.RingGeometry(1.82, 1.86, 48), ringMat);
    ring2.rotation.x = -Math.PI / 2;
    ring2.position.y = 0.009;
    this.group.add(ring2);
    const hazardMat = m.hazard;
    for (const [x, z, w, d] of [[0, -5.2, 3.2, 0.12], [0, 5.2, 3.2, 0.12], [-5.2, 0, 0.12, 3.2], [5.2, 0, 0.12, 3.2]]) {
      box(this.group, { w, h: 0.012, d, x, y: 0.01, z, material: hazardMat, cast: false });
    }
    // Painted AP-09 insignia.
    const decal = new THREE.Mesh(new THREE.CircleGeometry(1.35, 8), new THREE.MeshBasicMaterial({ color: 0x7f8f4c, transparent: true, opacity: 0.075 }));
    decal.rotation.x = -Math.PI / 2;
    decal.position.set(0, 0.006, 0.8);
    this.group.add(decal);
  }

  addLighting() {
    const lightSpecs = [
      { pos: [0, 4.18, -3.7], color: 0xb5ffe1, intensity: 24, distance: 8.5 },
      { pos: [0, 4.18, 3.7], color: 0xa8f5d4, intensity: 22, distance: 8.5 },
      { pos: [-4.5, 3.3, 0], color: 0x7fdcb8, intensity: 10, distance: 7 },
      { pos: [4.5, 3.3, 1.2], color: 0xa7df93, intensity: 9, distance: 6 },
      { pos: [0, 1.3, 0.8], color: 0x6deac3, intensity: 7, distance: 5 },
    ];
    for (const spec of lightSpecs) {
      const light = new THREE.PointLight(spec.color, spec.intensity, spec.distance, 1.7);
      light.position.set(...spec.pos);
      this.group.add(light);
      this.lights.push(light);
    }
    const fill = new THREE.PointLight(0xffc889, 9, 7, 2);
    fill.position.set(0, 3, 6.2);
    this.group.add(fill);
    this.lights.push(fill);
  }

  buildDoors() {
    const defs = [
      { id: 'N', label: 'B-1', name: 'NORTH AIRLOCK', pos: new THREE.Vector3(0, 0, -7.5), outward: new THREE.Vector3(0, 0, -1), angle: 0 },
      { id: 'S', label: 'B-2', name: 'SOUTH AIRLOCK', pos: new THREE.Vector3(0, 0, 7.5), outward: new THREE.Vector3(0, 0, 1), angle: Math.PI },
      { id: 'E', label: 'B-3', name: 'EAST AIRLOCK', pos: new THREE.Vector3(7.5, 0, 0), outward: new THREE.Vector3(1, 0, 0), angle: Math.PI / 2 },
      { id: 'W', label: 'B-4', name: 'WEST AIRLOCK', pos: new THREE.Vector3(-7.5, 0, 0), outward: new THREE.Vector3(-1, 0, 0), angle: -Math.PI / 2 },
    ];
    for (const def of defs) this.doors.push(this.buildDoor(def));
  }

  buildDoor(def) {
    const m = this.materials;
    const group = new THREE.Group();
    group.position.copy(def.pos);
    group.rotation.y = def.angle;
    this.group.add(group);

    const doorW = 3.15;
    const doorH = 3.62;
    const left = new THREE.Vector3(-def.outward.z, 0, def.outward.x).multiplyScalar(-1);

    // Heavy frame with bolts.
    for (const side of [-1, 1]) {
      box(group, { w: 0.42, h: 3.86, d: 0.58, x: side * 1.79, y: 1.93, z: 0, material: m.steelDark });
      for (let i = 0; i < 10; i += 1) {
        box(group, { w: 0.075, h: 0.075, d: 0.03, x: side * 1.79, y: 0.42 + i * 0.33, z: 0.31, material: m.steel, cast: false });
      }
    }
    box(group, { w: 4.0, h: 0.5, d: 0.58, x: 0, y: 3.86, z: 0, material: m.steelDark });
    box(group, { w: 3.47, h: 0.1, d: 0.64, x: 0, y: 3.55, z: 0, material: m.hazard, cast: false });
    box(group, { w: 0.38, h: 0.07, d: 0.7, x: 0, y: 4.12, z: 0, material: m.trim });

    // Door slabs.
    const panelMat = m.steel;
    const panelDark = m.steelDark;
    const panels = [];
    for (const side of [-1, 1]) {
      const panelGroup = new THREE.Group();
      panelGroup.position.x = side * 0.75;
      group.add(panelGroup);
      const slab = box(panelGroup, { w: 1.51, h: 3.42, d: 0.26, y: 1.72, material: panelMat });
      for (const y of [0.55, 1.7, 2.74]) {
        box(panelGroup, { w: 1.4, h: 0.11, d: 0.32, y, material: panelDark });
        box(panelGroup, { w: 1.23, h: 0.035, d: 0.33, y: y + 0.1, material: m.hazard, cast: false });
      }
      // Piston rails.
      box(panelGroup, { w: 0.16, h: 2.65, d: 0.35, x: side * 0.52, y: 1.72, material: panelDark });
      box(panelGroup, { w: 0.055, h: 2.25, d: 0.38, x: side * 0.52, y: 1.72, material: m.cyanGlow, cast: false });
      const lightMat = m.redGlow.clone();
      const indicator = box(panelGroup, { w: 0.12, h: 0.12, d: 0.03, x: side * 0.27, y: 3.18, z: 0.16, material: lightMat, cast: false });
      panels.push({ group: panelGroup, side, indicator, baseX: side * 0.75 });
    }
    // Upper warning stripes on open panels.
    box(group, { w: 1.45, h: 3.42, d: 0.02, x: 0, y: 1.72, z: 0.145, material: m.warning, cast: false });
    // Hydraulic roof pistons.
    for (const side of [-1, 1]) {
      const piston = box(group, { w: 0.15, h: 0.3, d: 0.8, x: side * 0.85, y: 3.72, z: 0.1, material: m.rust });
      piston.rotation.x = 0.1;
      box(group, { w: 0.1, h: 0.1, d: 0.9, x: side * 0.85, y: 3.7, z: 0.42, material: m.steel, cast: false });
    }

    // Tactile control switch, mounted on the LEFT side as viewed from inside.
    const switchGroup = new THREE.Group();
    const switchLocal = left.clone().multiplyScalar(2.18);
    switchGroup.position.set(switchLocal.x, 1.35, left.x !== 0 ? 0.11 : 0.11);
    // For side-on doors, move the switch into the lobby.
    const inward = def.outward.clone().multiplyScalar(-1);
    switchGroup.position.x = switchLocal.x + inward.x * 0.28;
    switchGroup.position.z = switchLocal.z + inward.z * 0.28;
    group.add(switchGroup);

    box(switchGroup, { w: 0.42, h: 0.66, d: 0.16, material: m.steelDark });
    box(switchGroup, { w: 0.34, h: 0.5, d: 0.19, material: m.steel });
    const leverPivot = new THREE.Group();
    leverPivot.position.set(0, 0.08, 0.14);
    switchGroup.add(leverPivot);
    box(leverPivot, { w: 0.06, h: 0.28, d: 0.06, y: -0.12, material: m.rust });
    box(leverPivot, { w: 0.11, h: 0.085, d: 0.15, y: -0.26, material: m.hazard });
    const swLightMat = m.greenGlow.clone();
    const swLight = box(switchGroup, { w: 0.075, h: 0.075, d: 0.04, x: 0.13, y: 0.22, z: 0.11, material: swLightMat, cast: false });
    const swRing = new THREE.Mesh(new THREE.RingGeometry(0.1, 0.12, 12), new THREE.MeshBasicMaterial({ color: 0x81e16d, side: THREE.DoubleSide, transparent: true, opacity: 0.6 }));
    swRing.position.set(0.13, 0.22, 0.12);
    switchGroup.add(swRing);

    // Label plate.
    const labelTexture = makeTextTexture(`AIRLOCK ${def.label}`, { width: 256, height: 64, size: 22, color: '#b9d391', bg: '#111b13', subtle: true });
    plane(switchGroup, { w: 0.5, h: 0.14, y: 0.45, z: 0.085, material: new THREE.MeshBasicMaterial({ map: labelTexture, toneMapped: false }) });

    // Exterior hazard chevrons.
    const outsideSign = new THREE.Mesh(new THREE.PlaneGeometry(1.35, 0.27), new THREE.MeshBasicMaterial({
      map: makeTextTexture(`M-08 HABITAT // ${def.name}`, { width: 512, height: 80, size: 26, color: '#bcce8c', bg: '#13170e' }),
      toneMapped: false,
    }));
    outsideSign.position.set(0, 3.1, -0.37);
    outsideSign.rotation.y = Math.PI;
    group.add(outsideSign);

    // Collider blocking the doorway when closed.
    const collider = {
      minX: def.pos.x - (def.outward.x !== 0 ? 0.4 : 1.6),
      maxX: def.pos.x + (def.outward.x !== 0 ? 0.4 : 1.6),
      minZ: def.pos.z - (def.outward.z !== 0 ? 0.4 : 1.6),
      maxZ: def.pos.z + (def.outward.z !== 0 ? 0.4 : 1.6),
      kind: 'door',
      active: true,
    };
    this.colliders.push(collider);

    const door = {
      ...def,
      group,
      panels,
      leverPivot,
      swLight,
      swRing,
      collider,
      progress: 0,
      target: 0,
      state: 'closed',
      busy: false,
      moveTime: 0,
      switchPosition: new THREE.Vector3(),
      switchGroup,
      indicatorMaterials: panels.map((p) => p.indicator.material),
    };
    switchGroup.getWorldPosition(door.switchPosition);
    const worldSwitch = new THREE.Vector3();
    switchGroup.getWorldPosition(worldSwitch);
    door.switchPosition.copy(worldSwitch);
    door.interactable = {
      id: `door-${def.id}`,
      kind: 'door',
      label: `HYDRAULIC DOOR ${def.label}`,
      action: () => this.toggleDoor(door),
      position: worldSwitch,
      range: 2.1,
      door,
    };
    this.interactables.push(door.interactable);
    return door;
  }

