510:   onKeyDown(event) {
511:     const code = event.code;
512:     if (['KeyW', 'KeyA', 'KeyS', 'KeyD', 'ShiftLeft', 'ShiftRight', 'Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'KeyE', 'KeyC', 'KeyV', 'KeyF', 'KeyM', 'Tab'].includes(code)) {
513:       event.preventDefault();
514:     }
515:     if (code === 'KeyM') {
516:       if (this.state === 'playing') this.openMap();
517:       else if (this.state === 'map') this.closeMap();
518:       return;
519:     }
520:     if (code === 'Escape') {
521:       if (this.state === 'map') this.closeMap();
522:       return;
523:     }
524:     if (this.state !== 'playing') return;
525:     if (event.repeat) {
526:       this.keys.add(code);
527:       return;
528:     }
529:     this.keys.add(code);
530:     if (code === 'KeyE') this.tryInteract();
531:     if (code === 'KeyV') this.toggleCamera();
532:     if (code === 'KeyF') this.toggleFlashlight();
533:     if (code === 'KeyC') this.toggleCrouch();
