549:     let forwardAmount = 0;
550:     let rightAmount = 0;
551:     if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) forwardAmount += 1;
552:     if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) forwardAmount -= 1;
553:     if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) rightAmount += 1;
554:     if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) rightAmount -= 1;
555:     if (this.touchMove.active) {
556:       forwardAmount += -this.touchMove.y;
557:       rightAmount += this.touchMove.x;
558:     }
559:     _move.set(0, 0, 0).addScaledVector(_forward, forwardAmount).addScaledVector(_right, rightAmount);
560:     if (_move.lengthSq() > 1) _move.normalize();
561:     return {
562:       move: _move,
563:       sprint: this.keys.has('ShiftLeft') || this.keys.has('ShiftRight') || this.touchSprint,
564:       crouch: this.crouchToggle,
565:       jump: this.jumpQueued,
