853:   updateCamera(dt, time) {
854:     if (this.state === 'dead') {
855:       this.camera.position.y += Math.sin(time * 3) * 0.0004;
856:       return;
857:     }
858:     const isFirst = this.cameraMode === 'first';
859:     if (isFirst) {
860:       this.player.setHidden(true);
861:       this.fpArms.visible = true;
862:       const bobSpeed = this.player.speed;
863:       this.fpBob += dt * (1.4 + bobSpeed * 1.4);
864:       const bob = this.player.moving && this.player.onGround ? Math.sin(this.fpBob * 2.1) * 0.017 * clamp(bobSpeed / 4, 0, 1.4) : 0;
865:       this.camera.position.set(this.player.position.x, this.player.position.y + 1.62 + bob, this.player.position.z);
866:       const lookPitch = 0.22 - this.orbitPitch;
867:       _camDir.set(
868:         -Math.sin(this.camYaw) * Math.cos(lookPitch),
869:         Math.sin(lookPitch),
870:         -Math.cos(this.camYaw) * Math.cos(lookPitch),
871:       ).normalize();
872:       _target.copy(this.camera.position).addScaledVector(_camDir, 12);
873:       this.camera.lookAt(_target);
874:       this.fpArms.position.y = -0.28 + bob * 1.3;
875:       this.fpArms.rotation.z = Math.sin(this.fpBob * 1.05) * 0.008;
876:       this.camera.fov = damp(this.camera.fov, this.player.sprinting ? 69 : this.player.crouching ? 58 : 62, 6, dt);
877:       this.camera.updateProjectionMatrix();
878:       return;
879:     }
880:     this.player.setHidden(false);
881:     this.fpArms.visible = false;
882:     const crouchOffset = this.player.crouching ? -0.32 : 0;
883:     _target.set(this.player.position.x, this.player.position.y + 1.18 + crouchOffset, this.player.position.z);
884:     const distance = this.player.inside ? 3.15 : this.player.crouching ? 3.7 : 4.35;
885:     const cp = Math.cos(this.orbitPitch) * distance;
886:     _desiredCam.set(
887:       _target.x + Math.sin(this.camYaw) * cp,
888:       _target.y + Math.sin(this.orbitPitch) * distance,
889:       _target.z + Math.cos(this.camYaw) * cp,
890:     );
891:     // Camera collision: shorten the boom if the line crosses solid geometry.
892:     let maxT = 1;
893:     for (let t = 0.18; t <= 1; t += 0.075) {
894:       const sx = _target.x + (_desiredCam.x - _target.x) * t;
895:       const sz = _target.z + (_desiredCam.z - _target.z) * t;
896:       if (this.cameraBlockedAt(sx, sz)) {
897:         maxT = Math.max(0.16, t - 0.1);
898:         break;
899:       }
900:     }
901:     _desiredCam.lerpVectors(_target, _desiredCam, maxT);
