339:   buildForest() {
340:     const rng = new RNG(99173);
341:     const barkGeos = [];
342:     const leafDark = [];
343:     const leafMid = [];
344:     const leafLight = [];
345:     const trunkColliders = [];
346: 
347:     const addTree = (x, z, scale = 1) => {
348:       const ground = terrainHeight(x, z);
349:       const height = rng.range(5.2, 11.2) * scale;
350:       const trunkW = rng.range(0.52, 1.18) * scale;
351:       addBoxGeo(barkGeos, trunkW, height, trunkW, x, ground + height / 2, z, rng.range(-0.04, 0.04), rng.range(0, Math.PI), rng.range(-0.04, 0.04));
352:       // Root flares.
353:       for (let i = 0; i < 4; i += 1) {
354:         const a = (i / 4) * Math.PI * 2 + rng.range(-0.3, 0.3);
355:         addBoxGeo(barkGeos, trunkW * 0.4, trunkW * 0.9, trunkW * 1.8, x + Math.cos(a) * trunkW * 0.7, ground + trunkW * 0.32, z + Math.sin(a) * trunkW * 0.7, 0, -a, 0.65);
356:       }
357:       // Branches reaching into the canopy.
358:       for (let i = 0; i < 4; i += 1) {
359:         const a = rng.range(0, Math.PI * 2);
360:         const len = rng.range(1.4, 3.1) * scale;
361:         const by = ground + height * rng.range(0.62, 0.94);
362:         addBoxGeo(barkGeos, 0.13 * scale, len, 0.13 * scale, x + Math.cos(a) * len * 0.46, by, z + Math.sin(a) * len * 0.46, Math.PI / 2 * 0.86, -a + Math.PI / 2, 0);
363:       }
364:       const canopyBase = ground + height * rng.range(0.82, 1.02);
365:       const canopyR = rng.range(2.5, 4.7) * scale;
366:       const clusters = rng.int(7, 12);
367:       for (let i = 0; i < clusters; i += 1) {
368:         const a = rng.range(0, Math.PI * 2);
369:         const rad = rng.range(0, canopyR);
370:         const cx = x + Math.cos(a) * rad;
371:         const cz = z + Math.sin(a) * rad;
372:         const cy = canopyBase + rng.range(-0.3, 3.1) * scale;
373:         const size = rng.range(1.1, 2.6) * scale;
374:         const r = rng.next();
375:         const arr = r < 0.33 ? leafDark : r < 0.7 ? leafMid : leafLight;
376:         addBoxGeo(arr, size, size * rng.range(0.55, 0.95), size, cx, cy, cz, rng.range(-0.15, 0.15), rng.range(0, Math.PI), rng.range(-0.15, 0.15));
377:         if (size > 1.9) {
378:           addBoxGeo(arr, size * 0.7, size * 0.6, size * 0.7, cx + rng.range(-0.5, 0.5), cy + rng.range(-0.7, 0.5), cz + rng.range(-0.5, 0.5), 0, rng.range(0, Math.PI), 0);
379:         }
380:       }
381:       // Hanging pixel vines.
382:       if (rng.next() > 0.5) {
383:         for (let i = 0; i < rng.int(1, 3); i += 1) {
384:           const vx = x + rng.range(-canopyR, canopyR);
385:           const vz = z + rng.range(-canopyR, canopyR);
386:           const len = rng.range(1.4, 4.3) * scale;
387:           addBoxGeo(leafDark, 0.08, len, 0.08, vx, canopyBase - len / 2, vz, 0, 0, 0);
388:           addBoxGeo(leafMid, 0.4, 0.18, 0.4, vx, canopyBase - len, vz, 0, rng.range(0, Math.PI), 0);
389:         }
390:       }
391:       trunkColliders.push({ x, z, radius: Math.max(0.38, trunkW * 0.68) });
392:     };
393: 
394:     let attempts = 0;
395:     while (trunkColliders.length < 285 && attempts < 2400) {
396:       attempts += 1;
397:       const x = rng.range(-238, 238);
398:       const z = rng.range(-238, 238);
399:       const d = Math.hypot(x, z);
400:       if (d < 21) continue;
401:       if (Math.abs(x) < 5.5 && Math.abs(z) < 90) continue;
402:       if (Math.abs(z) < 5.5 && Math.abs(x) < 90) continue;
403:       if (d > 240) continue;
404:       // Thin clearings around objectives.
405:       if (this.nearPoint(x, z, -116, 73, 12) || this.nearPoint(x, z, 142, -94, 12) || this.nearPoint(x, z, 47, 173, 12)) continue;
406:       // Some natural clustering leaves open tracking fields.
407:       const density = 1 - Math.max(0, Math.sin(x * 0.031) * Math.cos(z * 0.027)) * 0.5;
408:       if (rng.next() > density * 0.84) continue;
409:       addTree(x, z, rng.range(0.72, 1.5));
410:     }
411: 
412:     const makeMerged = (list, material, cast = true) => {
413:       if (!list.length) return null;
414:       const merged = mergeGeometries(list, false);
415:       const mesh = new THREE.Mesh(merged, material);
416:       mesh.castShadow = cast;
417:       mesh.receiveShadow = true;
418:       this.group.add(mesh);
419:       for (const geo of list) geo.dispose();
420:       return mesh;
421:     };
422:     makeMerged(barkGeos, this.materials.bark, true);
423:     makeMerged(leafDark, this.materials.leafDark, true);
424:     makeMerged(leafMid, this.materials.leafMid, true);
425:     makeMerged(leafLight, this.materials.leafLight, true);
426:     this.treeColliders = trunkColliders;
427: 
428:     this.buildUndergrowth(rng);
429:     this.buildRocks(rng);
430:   }
