432:   buildUndergrowth(rng) {
433:     const bush = [];
434:     const fern = [];
435:     const reed = [];
436:     const leafMats = [this.materials.leafDark, this.materials.leafMid, this.materials.leafLight];
437:     for (let i = 0; i < 750; i += 1) {
438:       const x = rng.range(-238, 238);
439:       const z = rng.range(-238, 238);
440:       const d = Math.hypot(x, z);
441:       if (d < 12 || d > 242) continue;
442:       if (Math.abs(x) < 3.5 && Math.abs(z) < 85) continue;
443:       if (Math.abs(z) < 3.5 && Math.abs(x) < 85) continue;
444:       const y = terrainHeight(x, z);
445:       const arr = rng.next() < 0.45 ? bush : rng.next() < 0.7 ? fern : reed;
446:       const s = rng.range(0.35, 1.25);
447:       if (arr === bush) {
448:         const count = rng.int(2, 5);
449:         for (let j = 0; j < count; j += 1) {
450:           addBoxGeo(bush, rng.range(0.4, 1.1) * s, rng.range(0.3, 0.8) * s, rng.range(0.4, 1.0) * s, x + rng.range(-0.45, 0.45) * s, y + rng.range(0.18, 0.42) * s, z + rng.range(-0.45, 0.45) * s, 0, rng.range(0, Math.PI), 0);
451:         }
452:       } else if (arr === fern) {
453:         for (let j = 0; j < 5; j += 1) {
454:           const a = (j / 5) * Math.PI * 2 + rng.range(-0.3, 0.3);
455:           addBoxGeo(fern, 0.08, rng.range(0.5, 1.2) * s, 0.6 * s, x + Math.cos(a) * 0.3 * s, y + 0.3 * s, z + Math.sin(a) * 0.3 * s, 0.28, a, 0.62);
456:         }
457:       } else {
458:         for (let j = 0; j < 3; j += 1) {
459:           addBoxGeo(reed, 0.05, rng.range(0.8, 1.7) * s, 0.05, x + rng.range(-0.3, 0.3) * s, y + 0.5 * s, z + rng.range(-0.3, 0.3) * s, rng.range(-0.15, 0.15), 0, rng.range(-0.15, 0.15));
460:         }
461:       }
462:     }
463:     for (const [list, mat] of [[bush, leafMats[0]], [fern, leafMats[1]], [reed, leafMats[2]]]) {
464:       if (!list.length) continue;
465:       const merged = mergeGeometries(list, false);
466:       const mesh = new THREE.Mesh(merged, mat);
467:       mesh.castShadow = false;
468:       mesh.receiveShadow = true;
469:       this.group.add(mesh);
470:       for (const g of list) g.dispose();
471:     }
472:   }
