474:   buildRocks(rng) {
475:     const rockGeos = [];
476:     const mossGeos = [];
477:     for (let i = 0; i < 165; i += 1) {
478:       const x = rng.range(-240, 240);
479:       const z = rng.range(-240, 240);
480:       const d = Math.hypot(x, z);
481:       if (d < 14 || d > 240) continue;
482:       if (Math.abs(x) < 4 && Math.abs(z) < 70) continue;
483:       if (Math.abs(z) < 4 && Math.abs(x) < 70) continue;
484:       const y = terrainHeight(x, z);
485:       const s = rng.range(0.35, 2.2);
486:       const geo = new THREE.DodecahedronGeometry(s, 0);
487:       geo.scale(1, rng.range(0.5, 0.9), rng.range(0.75, 1.2));
488:       geo.rotateY(rng.range(0, Math.PI));
489:       geo.translate(x, y + s * 0.32, z);
490:       rockGeos.push(geo);
491:       if (rng.next() > 0.52) {
492:         const mossGeo = new THREE.DodecahedronGeometry(s * 0.98, 0);
493:         mossGeo.scale(1.04, 0.3, 1.06);
494:         mossGeo.translate(x, y + s * 0.72, z);
495:         mossGeos.push(mossGeo);
496:       }
497:       if (s > 1.0) this.rockColliders.push({ x, z, radius: s * 0.8 });
498:     }
499:     for (const [list, mat] of [[rockGeos, this.materials.rock], [mossGeos, this.materials.rockMoss]]) {
500:       if (!list.length) continue;
501:       const merged = mergeGeometries(list, false);
502:       const mesh = new THREE.Mesh(merged, mat);
503:       mesh.castShadow = true;
504:       mesh.receiveShadow = true;
505:       this.group.add(mesh);
506:       for (const g of list) g.dispose();
507:     }
508:   }
