190:   buildSky() {
191:     const skyGeo = new THREE.SphereGeometry(520, 32, 18);
192:     const skyMat = new THREE.ShaderMaterial({
193:       side: THREE.BackSide,
194:       depthWrite: false,
195:       fog: false,
196:       uniforms: {
197:         topColor: { value: new THREE.Color(0x061017) },
198:         horizonColor: { value: new THREE.Color(0x3a4f39) },
199:         sunColor: { value: new THREE.Color(0x7e825e) },
200:       },
201:       vertexShader: `
202:         varying vec3 vWorld;
203:         void main() {
204:           vec4 world = modelMatrix * vec4(position, 1.0);
205:           vWorld = world.xyz;
206:           gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
207:         }
208:       `,
209:       fragmentShader: `
210:         uniform vec3 topColor;
211:         uniform vec3 horizonColor;
212:         uniform vec3 sunColor;
213:         varying vec3 vWorld;
214:         void main() {
215:           vec3 dir = normalize(vWorld);
216:           float h = clamp(dir.y * 1.35 + 0.08, 0.0, 1.0);
217:           vec3 col = mix(horizonColor, topColor, pow(h, 0.67));
218:           float glow = pow(max(0.0, dot(dir, normalize(vec3(-0.45, 0.3, -0.84)))), 18.0);
219:           col += sunColor * glow * 0.25;
220:           float dither = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453);
221:           col += (dither - 0.5) * 0.014;
222:           gl_FragColor = vec4(col, 1.0);
223:         }
224:       `,
225:     });
226:     this.sky = new THREE.Mesh(skyGeo, skyMat);
227:     this.scene.add(this.sky);
228: 
229:     // Low, fog-dimmed moon.
230:     const moon = new THREE.Mesh(
231:       new THREE.SphereGeometry(7.2, 16, 10),
232:       new THREE.MeshBasicMaterial({ color: 0xbac59c, fog: false, toneMapped: false }),
233:     );
234:     moon.position.set(-180, 205, -330);
235:     this.scene.add(moon);
236:     this.moon = moon;
237: 
238:     const starCount = 340;
239:     const starGeo = new THREE.BufferGeometry();
240:     const starPos = new Float32Array(starCount * 3);
241:     for (let i = 0; i < starCount; i += 1) {
242:       const theta = Math.random() * Math.PI * 2;
243:       const phi = Math.random() * Math.PI * 0.24;
244:       const r = 430;
245:       starPos[i * 3] = Math.cos(theta) * Math.sin(phi + 0.12) * r;
246:       starPos[i * 3 + 1] = Math.cos(phi) * r * 0.85 + 50;
247:       starPos[i * 3 + 2] = Math.sin(theta) * Math.sin(phi + 0.12) * r;
248:     }
249:     starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
250:     const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({ color: 0xc8d5ae, size: 1.2, sizeAttenuation: false, fog: false, transparent: true, opacity: 0.62 }));
251:     stars.frustumCulled = false;
252:     this.scene.add(stars);
253:   }
