578:   tryInteract() {
579:     if (this.state !== 'playing') return;
580:     const item = this.currentInteractable;
581:     if (!item) return;
582:     if (item.kind === 'door') {
583:       this.audio.switchClick();
584:       this.doorsTouched += 1;
585:     }
586:     if (item.kind === 'terminal') this.audio.terminal();
587:     item.action();
588:     this.updateInteraction(this.ui, true);
589:   }
