864:   updateCamera(dt, time) {
865:     if (this.state === 'dead') {
866:       this.camera.position.y += Math.sin(time * 3) * 0.0004;
867:       return;
868:     }
869:     const isFirst = this.cameraMode === 'first';
870:     if (isFirst) {
871:       this.player.setHidden(true);
872:       this.fpArms.visible = true;
873:       const bobSpeed = this.player.speed;
874:       this.fpBob += dt * (1.4 + bobSpeed * 1.4);
875:       const bob = this.player.moving && this.player.onGround ? Math.sin(this.fpBob * 2.1) * 0.017 * clamp(bobSpeed / 4, 0, 1.4) : 0;
876:       this.camera.position.set(this.player.position.x, this.player.position.y + 1.62 + bob, this.player.position.z);
877:       const lookPitch = 0.22 - this.orbitPitch;
878:       _camDir.set(
879:         -Math.sin(this.camYaw) * Math.cos(lookPitch),
880:         Math.sin(lookPitch),
881:         -Math.cos(this.camYaw) * Math.cos(lookPitch),
882:       ).normalize();
883:       _target.copy(this.camera.position).addScaledVector(_camDir, 12);
884:       this.camera.lookAt(_target);
885:       this.fpArms.position.y = -0.28 + bob * 1.3;
886:       this.fpArms.rotation.z = Math.sin(this.fpBob * 1.05) * 0.008;
887:       this.camera.fov = damp(this.camera.fov, this.player.sprinting ? 69 : this.player.crouching ? 58 : 62, 6, dt);
888:       this.camera.updateProjectionMatrix();
889:       return;
890:     }
891:     this.player.setHidden(false);
892:     this.fpArms.visible = false;
893:     const crouchOffset = this.player.crouching ? -0.32 : 0;
894:     _target.set(this.player.position.x, this.player.position.y + 1.18 + crouchOffset, this.player.position.z);
895:     // Over-the-shoulder framing keeps the ape from masking the interaction
896:     // point and gives the lobby a more cinematic silhouette.
897:     _camRight.set(Math.cos(this.camYaw), 0, -Math.sin(this.camYaw));
898:     const portrait = this.camera.aspect < 0.8;
899:     const shoulder = this.player.inside ? (portrait ? 0.68 : 0.46) : (portrait ? 0.9 : 0.62);
900:     _target.addScaledVector(_camRight, shoulder);
901:     const distance = this.player.inside
902:       ? (portrait ? 3.55 : 3.05)
903:       : this.player.crouching ? 3.7 : (portrait ? 5.2 : 4.35);
904:     const cp = Math.cos(this.orbitPitch) * distance;
905:     _desiredCam.set(
906:       _target.x + Math.sin(this.camYaw) * cp,
907:       _target.y + Math.sin(this.orbitPitch) * distance,
908:       _target.z + Math.cos(this.camYaw) * cp,
909:     );
910:     // Camera collision: shorten the boom if the line crosses solid geometry.
911:     let maxT = 1;
912:     for (let t = 0.18; t <= 1; t += 0.075) {
913:       const sx = _target.x + (_desiredCam.x - _target.x) * t;
914:       const sz = _target.z + (_desiredCam.z - _target.z) * t;
915:       if (this.cameraBlockedAt(sx, sz)) {
916:         maxT = Math.max(0.16, t - 0.1);
917:         break;
918:       }
919:     }
920:     _desiredCam.lerpVectors(_target, _desiredCam, maxT);
921:     const minY = (this.player.inside ? 0.25 : this.player.position.y + 0.35);
922:     _desiredCam.y = Math.max(_desiredCam.y, minY);
923:     if (this.player.inside) _desiredCam.y = Math.min(_desiredCam.y, 4.15);
924:     const speed = this.snapCamera ? 200 : 12;
925:     this.camera.position.lerp(_desiredCam, 1 - Math.exp(-speed * dt));
926:     if (this.snapCamera) this.snapCamera = false;
927:     _look.copy(_target);
928:     // Subtle aim lead in the direction of travel.
929:     if (this.player.moving) {
930:       _look.x += Math.sin(this.player.visualYaw) * this.player.speed * 0.045;
931:       _look.z += Math.cos(this.player.visualYaw) * this.player.speed * 0.045;
932:     }
933:     this.shake.offset(_shake);
934:     this.camera.position.add(_shake);
935:     this.camera.lookAt(_look);
936:     this.camera.fov = damp(this.camera.fov, this.player.sprinting ? 66 : portrait ? 68 : 61, 4, dt);
937:     this.camera.updateProjectionMatrix();
938:   }
