940:   cameraBlockedAt(x, z) {
941:     for (const c of this.lab.colliders) {
942:       if (!c.active) continue;
943:       if (x > c.minX && x < c.maxX && z > c.minZ && z < c.maxZ) return true;
944:     }
945:     if (!this.lab.isInside(x, z, -0.4)) {
946:       for (const tree of this.jungle.treeColliders) {
947:         const dx = x - tree.x;
948:         const dz = z - tree.z;
949:         if (dx * dx + dz * dz < (tree.radius + 0.22) ** 2) return true;
950:       }
951:     }
952:     return false;
953:   }
